#!/usr/bin/env python
import json, urllib.parse, urllib.request
import pandas as pd

subjects = [
    "anatomy", "astronomy", "college_biology", "college_chemistry",
    "college_physics", "conceptual_physics", "high_school_biology",
    "high_school_chemistry", "high_school_physics",
]
rows = []
for subject in subjects:
    for split in ("dev", "validation", "test"):
        offset = 0
        while True:
            query = urllib.parse.urlencode({
                "dataset": "cais/mmlu", "config": subject, "split": split,
                "offset": offset, "length": 100,
            })
            with urllib.request.urlopen(
                "https://datasets-server.huggingface.co/rows?" + query, timeout=30
            ) as response:
                payload = json.load(response)
            batch = payload.get("rows", [])
            for item in batch:
                row = item["row"]
                rows.append({
                    "question": row["question"],
                    "choices": json.dumps(row["choices"]),
                    "answer_idx": int(row["answer"]),
                    "source": "mmlu_" + subject,
                })
            offset += len(batch)
            if not batch or offset >= payload.get("num_rows_total", offset):
                break
pd.DataFrame(rows).drop_duplicates(subset=["question", "choices"]).to_csv(
    "/app/data/mmlu_science.csv", index=False
)
print(f"saved {len(rows)} rows")

