#!/usr/bin/env python
import json, pandas as pd
from qa_finetune import read_rows, split_rows

train, _ = split_rows(read_rows('/app/data/qa_train.csv'), .15, 31415)
for source in ('openbookqa', 'arc_easy', 'sciq'):
    rows=[]
    for r in train:
        if r['source']==source:
            rows.append({**r, 'choices':json.dumps(r['choices'])})
    pd.DataFrame(rows).to_csv(f'/app/data/train_{source}.csv',index=False)
    print(source,len(rows))

